      {screen === "contextOutcome" && <ContextOutcomeScreen go={go} role={role} />}
      {screen === "node" && (
        <NodeScreen
          go={go}
          role={role}
          online={nodeOnline}
          setOnline={setNodeOnline}
          pause={pause}
          clearPause={() => setPause(null)}
        />
      )}
      {screen === "selftest" && <SelfTestScreen go={go} />}
      {screen === "pause" && (
        <PauseScreen
          go={go}
          duration={pauseDuration}
          setDuration={setPauseDuration}
          reason={pauseReason}
          setReason={setPauseReason}
        />
      )}
      {screen === "pauseConfirm" && (
        <PauseConfirmScreen
          go={go}
          duration={pauseDuration}
          reason={pauseReason}
          onConfirm={(reasonLabel, resumeAt) => setPause({ reasonLabel, resumeAt })}
        />
      )}
      {screen === "history" && <HistoryScreen />}
      {screen === "contacts" && (
        <ContactsScreen go={go} role={role} onSave={() => setContactsSaved(true)} />
      )}
      {screen === "privacy" && <PrivacyScreen go={go} />}
      {screen === "profile" && (
        <ProfileScreen
          go={go}
          role={role}
          largeText={largeText}
          setLargeText={setLargeText}
          language={language}
          setLanguage={setLanguage}
        />
      )}

      {showNav && <BottomNav tab={tab} setTab={setTab} go={go} />}
    </AppFrame>
  );
}

