function KpiStrip() {
  return (
    <div className="border-b border-slate-200 bg-slate-50 px-3 py-2">
      <div className="grid grid-cols-2 gap-2 sm:grid-cols-4 xl:grid-cols-7">
        {dashboardKpis.map((kpi) => (
          <div key={kpi.label} className="rounded-lg border border-slate-200 bg-white px-3 py-2 shadow-sm">
            <p className="truncate text-[9px] font-bold uppercase tracking-wider text-slate-400">{kpi.label}</p>
