}

function IncidentCard({
  incident,
  isSelected,
  onSelect,
  onToggleFlag,
}: {
  incident: Incident;
  isSelected: boolean;
  onSelect: () => void;
  onToggleFlag: () => void;
}) {
  const sev = severityColor(incident.severity);
  const confidence = getConfidence(incident);
  const band = confidenceBand(confidence);
  const verificationStatus = getVerificationStatus(incident);
  const timer = getTimer(incident);

  return (
    <div
      role="button"
      tabIndex={0}
      onClick={onSelect}
      onKeyDown={(e) => {
        if (e.key === 'Enter' || e.key === ' ') {
          e.preventDefault();
          onSelect();
        }
      }}
      className={`w-full text-left rounded-lg border p-2.5 transition-all duration-150 group cursor-pointer ${
        isSelected
          ? `${sev.bg} bg-opacity-30 ${sev.border} ring-1 ${sev.ring}`
          : 'bg-white border-slate-150 hover:bg-slate-50 hover:border-slate-300'
      }`}
    >
      <div className="flex items-start justify-between mb-2">
        <div className="flex items-center gap-2">
          <div className={`w-7 h-7 rounded-md ${sev.bg} ${sev.text} flex items-center justify-center flex-shrink-0 shadow-sm border border-white/50`}>
            {typeIcon(incident.type)}
          </div>
          <div>
            <p className="text-[13px] font-bold text-slate-900 leading-tight tracking-tight">{incident.type}</p>
            <p className="text-[10px] font-mono font-medium text-slate-400">{incident.id}</p>
          </div>
        </div>
        <button
          onClick={(e) => { e.stopPropagation(); onToggleFlag(); }}
          className={`p-1 rounded-md border transition-colors ${
            incident.flagged
              ? 'text-red-600 bg-red-50 border-red-200 hover:bg-red-100'
              : 'text-red-300 bg-red-50/40 border-red-100 hover:bg-red-50'
          }`}
          title={incident.flagged ? 'Unflag' : 'Flag'}
        >
          {incident.flagged ? <Flag className="w-3 h-3" /> : <FlagOff className="w-3 h-3" />}
        </button>
      </div>
      <div className="mb-2.5 rounded-md border border-slate-100 bg-slate-50/50 p-1.5">
        <div className="flex items-center gap-1.5">
          <MapPin className="w-3 h-3 text-slate-400 flex-shrink-0" />
          <p className="text-[11px] font-bold text-slate-700 truncate">{incident.location}</p>
        </div>
        <p className="mt-0.5 pl-[18px] text-[9px] font-semibold uppercase tracking-wider text-slate-400">Registered HDB unit</p>
      </div>
      <div className="mb-2 grid grid-cols-2 gap-1.5">
        <div className="rounded border border-slate-100 bg-white px-2 py-1">
          <p className="text-[8px] font-bold uppercase tracking-wider text-slate-400">Confidence</p>
          <p className="text-[10.5px] font-bold text-slate-800">{confidence}% {band}</p>
        </div>
        <div className="rounded border border-slate-100 bg-white px-2 py-1">
          <p className="text-[8px] font-bold uppercase tracking-wider text-slate-400">Timer</p>
          <p className="text-[10.5px] font-bold text-slate-800">{timer}</p>
        </div>
      </div>
      <div className="mb-2 flex items-start gap-1.5 rounded-md border border-slate-100 bg-white p-1.5">
        <CheckCircle2 className="mt-0.5 h-3 w-3 shrink-0 text-teal-600" />
        <p className="text-[10.5px] font-semibold text-slate-700">Status: {verificationStatus}</p>
      </div>
      <div className="hidden items-center gap-1.5 mb-2.5 bg-slate-50/50 p-1.5 rounded-md border border-slate-100">
        <MapPin className="w-3 h-3 text-slate-400 flex-shrink-0" />
        <p className="text-[10.5px] font-medium text-slate-600 truncate">{incident.location}</p>
      </div>
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-1.5">
          <Clock className="w-3 h-3 text-slate-400" />
          <div className="flex items-baseline gap-1">
            <span className="text-[9px] uppercase tracking-wider font-bold text-slate-400">Elapsed</span>
            <span className="text-[10.5px] font-mono font-bold text-slate-700">{incident.elapsedTime}</span>
