// â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
// Incident Detail Strip (compact, attached below map)
// â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€

function IncidentDetailStrip({
  incident,
  onRunSimulation,
  simulationLoading,
}: {
  incident: Incident | null;
  onRunSimulation: (scenario: EchoSyncScenarioId) => void;
  simulationLoading: EchoSyncScenarioId | null;
}) {
  const [vlmLoading, setVlmLoading] = useState(false);
  const [vlmResult, setVlmResult] = useState<VlmVerificationResult | null>(null);
  const [vlmError, setVlmError] = useState(false);

  useEffect(() => {
    setVlmLoading(false);
    setVlmResult(null);
    setVlmError(false);
  }, [incident?.id]);

  const handleRunVisualVerification = async () => {
    if (!incident?.simulation) return;

    setVlmLoading(true);
    setVlmError(false);

    try {
      const response = await fetch('/api/vlm-verify', {
        method: 'POST',
        headers: { 'content-type': 'application/json' },
        body: JSON.stringify({
          caseId: incident.id,
          caseType: incident.type,
          title: incident.type,
          location: incident.location,
          confidence: incident.simulation.confidence,
          riskLevel: incident.simulation.riskLevel,
          priority: incident.severity,
          sensorSummary: incident.simulation.aiReasoningLine || incident.evidence.join(' + '),
        }),
      });

      if (!response.ok) throw new Error('VLM verification unavailable');

      setVlmResult(await response.json() as VlmVerificationResult);
    } catch {
      setVlmResult(null);
      setVlmError(true);
    } finally {
      setVlmLoading(false);
    }
  };

  if (!incident) {
    return (
      <div className="bg-white border-t border-slate-200 px-4 py-4 flex items-center justify-center text-slate-500 text-[12px] h-[68px]">
        Select an incident from the list to view dispatch details and actions.
      </div>
    );
  }

  const sev = severityColor(incident.severity);

  return (
    <div className="bg-white border-t border-slate-200 px-4 py-3 flex flex-col gap-2 shrink-0 max-h-[38%] overflow-y-auto overflow-x-hidden">
      {/* Top Row: Info + Actions */}
      <div className="flex items-start md:items-center justify-between gap-3 flex-col md:flex-row">
        {/* Info area */}
        <div className="min-w-0 flex-1 flex flex-wrap items-center gap-2">
          {/* Identity */}
          <div className="flex items-center gap-2 flex-shrink-0">
            <div className={`w-7 h-7 rounded-md ${sev.bg} ${sev.text} flex items-center justify-center shadow-sm border border-white/50`}>
              {typeIcon(incident.type)}
            </div>
            <div className="min-w-0 flex flex-col">
              <p className="text-[12px] font-bold text-slate-900 leading-tight">{incident.type} <span className="text-slate-400 font-mono font-medium text-[10px] ml-1">{incident.id}</span></p>
              <p className="text-[10px] font-medium text-slate-500">{incident.location}</p>
            </div>
          </div>

          <div className="w-px h-5 bg-slate-200 flex-shrink-0 mx-1 hidden sm:block" />

          {/* Stat Pills */}
          <div className="flex flex-wrap items-center gap-1.5">
            {[
              { label: 'Unit', value: incident.assignedUnit || 'None' },
              { label: 'Priority', value: incident.severity },
              { label: 'Elapsed', value: incident.elapsedTime },
              { label: 'Updated', value: incident.lastUpdated },
              { label: 'Status', value: incident.status },
            ].map((item) => (
              <div key={item.label} className="bg-slate-50 rounded px-2 py-0.5 border border-slate-100 flex items-baseline gap-1.5">
                <span className="text-[8px] font-bold uppercase tracking-wider text-slate-400">{item.label}</span>
                <span className="text-[10px] font-bold text-slate-700">{item.value}</span>
              </div>
            ))}
          </div>
        </div>

        {/* Action buttons */}
        <div className="shrink-0 flex items-center gap-1.5 self-end md:self-auto">
          <button className="flex items-center gap-1 px-3 py-1.5 rounded-md bg-teal-600 hover:bg-teal-700 text-white text-[10px] font-semibold transition-colors shadow-sm">
            <Send className="w-3.5 h-3.5" /> Dispatch
          </button>
          <button className="flex items-center gap-1 px-2.5 py-1.5 rounded-md bg-slate-100 hover:bg-slate-200 text-slate-700 text-[10px] font-semibold transition-colors border border-slate-200 shadow-sm">
            <MessageSquare className="w-3.5 h-3.5 text-slate-500" /> Chat
          </button>
          <button className="flex items-center gap-1 px-2.5 py-1.5 rounded-md bg-slate-100 hover:bg-slate-200 text-slate-700 text-[10px] font-semibold transition-colors border border-slate-200 shadow-sm">
            <Radio className="w-3.5 h-3.5 text-slate-500" /> Broadcast
          </button>
          <button className="flex items-center gap-1 px-3 py-1.5 rounded-md bg-emerald-600 hover:bg-emerald-700 text-white text-[10px] font-semibold transition-colors shadow-sm ml-1">
            <CheckCircle2 className="w-3.5 h-3.5" /> Resolve
          </button>
        </div>
      </div>

      {/* Bottom Row: Evidence Summary */}
      {incident.evidence && incident.evidence.length > 0 && (
        <div className="mt-1 flex flex-wrap items-center gap-2 text-xs bg-amber-50/50 p-2.5 rounded-md border border-amber-100 shadow-sm">
          <div className="flex min-w-0 flex-1 flex-wrap items-center gap-2">
            <span className="text-[10px] font-bold uppercase tracking-wider text-amber-700 flex-shrink-0 flex items-center gap-1.5">
               <AlertTriangle className="w-3.5 h-3.5" /> AI Alert Reasoning:
            </span>
            <span className="min-w-0 text-[11.5px] font-semibold text-slate-800 leading-snug">
              {incident.simulation?.aiReasoningLine || incident.evidence.join(' + ')}
            </span>
          </div>
          <div className="flex shrink-0 flex-wrap items-center gap-1.5">
            {simulationControls.map((control) => (
              <button
                key={control.id}
                type="button"
                onClick={() => onRunSimulation(control.id)}
                disabled={simulationLoading === control.id}
                className="rounded-md border border-slate-200 bg-white px-2.5 py-1 text-[10px] font-semibold text-slate-700 shadow-sm transition-colors hover:bg-slate-50 disabled:cursor-wait disabled:opacity-60"
              >
                {simulationLoading === control.id ? 'Loading...' : control.label}
              </button>
            ))}
          </div>
        </div>
      )}

      {incident.simulation && (
        <div className="grid gap-2 rounded-md border border-slate-100 bg-slate-50/70 p-2.5">
          <div className="grid grid-cols-2 gap-1.5 sm:grid-cols-4">
            {[
              { label: 'Confidence', value: `${incident.simulation.confidence}%` },
              { label: 'Immobile', value: incident.simulation.immobileTime },
              { label: 'Detect-to-alert', value: incident.simulation.detectionToAlert },
              { label: 'Risk', value: incident.simulation.riskLevel },
            ].map((metric) => (
              <div key={metric.label} className="min-w-0 rounded bg-white px-2 py-1.5 border border-slate-100">
                <p className="text-[8px] font-bold uppercase tracking-wider text-slate-400">{metric.label}</p>
                <p className="truncate text-[10px] font-bold text-slate-800">{metric.value}</p>
              </div>
            ))}
          </div>

          <div className="grid gap-1.5 text-[10.5px] text-slate-700 md:grid-cols-2">
            <p><span className="font-bold text-slate-500">Thermal presence:</span> {incident.simulation.detectorEvidence.thermal}</p>
            <p><span className="font-bold text-slate-500">Acoustic impact/distress:</span> {incident.simulation.detectorEvidence.acoustic}</p>
            <p><span className="font-bold text-slate-500">Under-mattress load mat:</span> {incident.simulation.detectorEvidence.loadMat}</p>
            <p><span className="font-bold text-slate-500">Door/fridge sensors:</span> {incident.simulation.detectorEvidence.doorFridge}</p>
            <p className="md:col-span-2"><span className="font-bold text-slate-500">Voice check-in:</span> {incident.simulation.detectorEvidence.voice}</p>
          </div>

          <div className="rounded bg-white px-2 py-1.5 border border-slate-100">
            <p className="text-[8px] font-bold uppercase tracking-wider text-slate-400">Recommended action</p>
            <p className="text-[10.5px] font-bold text-slate-800">{incident.simulation.recommendedAction}</p>
          </div>

          <div className="rounded bg-white px-2 py-1.5 border border-slate-100">
            <div className="flex flex-wrap items-center justify-between gap-2">
              <div>
                <p className="text-[8px] font-bold uppercase tracking-wider text-slate-400">Optional Visual Verification</p>
                <p className="text-[10px] font-medium text-slate-500">Activated only after sensor anomaly detection.</p>
              </div>
              <button
                type="button"
                onClick={handleRunVisualVerification}
                disabled={vlmLoading}
                className="rounded-md border border-slate-200 bg-white px-2.5 py-1 text-[10px] font-semibold text-slate-700 shadow-sm transition-colors hover:bg-slate-50 disabled:cursor-wait disabled:opacity-60"
              >
                {vlmLoading ? 'Verifying...' : 'Run Visual Verification'}
              </button>
            </div>
            {vlmLoading && (
              <p className="mt-1.5 text-[10.5px] font-semibold text-slate-500">Visual verification running...</p>
            )}
            {vlmError && (
              <p className="mt-1.5 text-[10.5px] font-semibold text-slate-600">
                Visual verification is unavailable. The dashboard remains on sensor fusion and confidence scoring.
              </p>
            )}
            {vlmResult && (
              <div className="mt-1.5 space-y-1">
                <div className="flex flex-wrap items-center gap-1.5">
                  <span className="text-[10.5px] font-semibold text-slate-700">{vlmResult.visualSummary}</span>
                  <span className="rounded bg-slate-100 px-1.5 py-0.5 text-[8px] font-bold uppercase tracking-wider text-slate-500">
                    {vlmResult.source === 'Fallback' ? 'Fallback Mode' : 'VLM Verified'}
                  </span>
                </div>
                <p className="text-[9px] font-mono font-semibold text-slate-400">Model: {vlmResult.model}</p>
              </div>
            )}
          </div>

          {incident.simulation.aiSummary && (
            <div className="rounded bg-white px-2 py-1.5 border border-slate-100">
              <p className="text-[8px] font-bold uppercase tracking-wider text-slate-400">
                AI Summary <span className="font-mono normal-case">({incident.simulation.aiSummary.source})</span>
              </p>
              <p className="text-[10.5px] font-semibold text-slate-700">{incident.simulation.aiSummary.summary}</p>
            </div>
          )}
        </div>
      )}

    </div>
  );
}

