      fetch('/api/nim-alert-summary', {
        method: 'POST',
        headers: { 'content-type': 'application/json' },
        body: JSON.stringify({
          caseId: alert.caseId,
          caseType: alert.caseType,
          location: simulatedIncident.location,
          confidence: alert.confidence,
          riskLevel: alert.riskLevel,
          detectors: {
