                </button>
              );
            })}
          </div>
          {/* Scrollable cards */}
          <div className="flex-1 overflow-y-auto p-2 space-y-1.5">
            {filteredIncidents.map(inc => (
              <IncidentCard
                key={inc.id}
                incident={inc}
                isSelected={inc.id === selectedId}
                onSelect={() => setSelectedId(inc.id)}
                onToggleFlag={() => handleToggleFlag(inc.id)}
