function typeIcon(type: string) {
  switch (type) {
    case 'Medical': return <HeartPulse className="w-4 h-4" />;
    case 'Fire': return <Flame className="w-4 h-4" />;
    case 'Fall Detection': return <Activity className="w-4 h-4" />;
    case 'Unresponsive Resident': return <AlertTriangle className="w-4 h-4" />;
    case 'Gas Leak': return <Wind className="w-4 h-4" />;
    default: return <AlertTriangle className="w-4 h-4" />;
  }
}

function riskToSeverity(riskLevel: EchoSyncSimulationResult['riskLevel']): Severity {
  return riskLevel;
}

function statusFromRisk(riskLevel: Severity): IncidentStatus {
  if (riskLevel === 'Low') return 'Resolved';
  if (riskLevel === 'Medium') return 'Active';
  if (riskLevel === 'High') return 'Active';
  return 'Operator Review';
}

function assignedUnitFromRisk(riskLevel: Severity) {
  if (riskLevel === 'Critical') return 'Operator review + CFR/AED suggestion';
  if (riskLevel === 'High') return 'Operator review queue';
  if (riskLevel === 'Medium') return 'Caregiver verification pending';
  return 'Caregiver follow-up / monitor';
}

function getConfidence(incident: Incident) {
  return incident.simulation?.confidence ?? (
    incident.severity === 'Critical' ? 91 : incident.severity === 'High' ? 87 : incident.severity === 'Medium' ? 68 : 38
  );
}

function confidenceBand(confidence: number) {
  if (confidence >= 80) return 'HIGH';
  if (confidence >= 55) return 'MED';
  return 'LOW';
}

function getVerificationStatus(incident: Incident) {
  if (incident.status === 'Resolved') return 'Resolved by caregiver';
  if (incident.severity === 'Medium') return 'Caregiver verification pending';
  if (incident.severity === 'High' || incident.severity === 'Critical') return 'Emergency operator review';
  return 'Needs verification';
}

function getTimer(incident: Incident) {
  if (incident.status === 'Resolved') return 'Completed';
  if (incident.severity === 'Medium') return '00:42 remaining';
  if (incident.severity === 'High') return 'Verification expired';
  if (incident.severity === 'Critical') return 'No response';
  return '01:00 remaining';
}

function getRecommendedPathway(incident: Incident) {
  const confidence = getConfidence(incident);
  if (confidence < 55) return 'Caregiver follow-up / monitor. Non-emergency advice: 1777 if assistance is needed.';
  if (incident.severity === 'Medium') return 'Caregiver verification';
  if (incident.severity === 'High') return 'Emergency operator review';
  if (incident.severity === 'Critical') return 'Escalate verified alert + myResponder-style CFR/AED suggestion';
  return 'Monitor / caregiver follow-up';
}

function getCaregiverStatus(incident: Incident) {
  if (incident.status === 'Resolved') {
    return {
      heading: 'Resolved by caregiver',
      status: 'Verified okay',
      response: 'Resident confirmed okay',
      timer: 'Completed',
      audit: 'Audit log: CGV-2026-0842',
      note: 'No emergency operator escalation required',
    };
  }

  return {
    heading: 'Caregiver verification',
    status: 'Notified',
    response: incident.severity === 'Critical' ? 'No response before window expired' : 'Pending',
    timer: getTimer(incident),
    audit: 'Audit log: Pending',
    note: 'Primary caregiver: Tan Mei Ling',
  };
}

function getNodeHealth(incident: Incident) {
  return {
    title: incident.id === 'INC-2026-086' ? 'Node offline' : 'Node health',
    device: 'Living Room Ceiling Hub',
    status: incident.id === 'INC-2026-086' ? 'Offline' : 'Online',
    heartbeat: incident.id === 'INC-2026-086' ? '18 minutes ago' : '30 seconds ago',
    wifi: incident.id === 'INC-2026-086' ? 'Disconnected' : 'Good',
    power: incident.id === 'INC-2026-086' ? 'Unknown' : 'Connected',
    selfTest: incident.id === 'INC-2026-086' ? 'Follow-up required' : 'Passed',
  };
}

function matchesFilter(incident: Incident, filter: IncidentFilter) {
  if (filter === 'All') return true;
  if (filter === 'Needs Verification') return incident.status !== 'Resolved';
  if (filter === 'Caregiver Pending') return getVerificationStatus(incident).includes('Caregiver');
  if (filter === 'High Confidence') return getConfidence(incident) >= 80;
  if (filter === 'Escalated') return getVerificationStatus(incident).includes('operator') || incident.severity === 'Critical';
  if (filter === 'Resolved') return incident.status === 'Resolved';
  return true;
}

function currentDashboardTime() {
  return new Date().toLocaleTimeString('en-US', {
    hour12: false,
    hour: '2-digit',
    minute: '2-digit',
  });
}

function getOperationalSummary(scenario: EchoSyncScenarioId) {
